package com.ftk.tpip.control.api.integration;
import com.ftk.tpip.control.application.integration.IntegrationBindingApplicationService;import com.ftk.tpip.integration.domain.model.BindingStatus;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/bindings")
public class IntegrationBindingController{private final IntegrationBindingApplicationService service;public IntegrationBindingController(IntegrationBindingApplicationService service){this.service=service;}
@PostMapping public ResponseEntity<IntegrationBindingResponse> create(@Valid @RequestBody CreateIntegrationBindingRequest r,@RequestHeader("X-Operator") @NotBlank @Size(max=100) String actor){var b=service.create(r.bindingCode(),r.bindingName(),r.operationId(),r.providerContractId(),r.ownerCode(),actor);return ResponseEntity.created(URI.create("/control/v1/bindings/"+b.id())).body(IntegrationBindingResponse.from(b));}
@GetMapping("/{id}") public IntegrationBindingResponse get(@PathVariable @Min(1) long id){return IntegrationBindingResponse.from(service.get(id));}
@GetMapping public IntegrationBindingPageResponse list(@RequestParam(required=false) @Min(1) Long operationId,@RequestParam(required=false) @Min(1) Long providerContractId,@RequestParam(required=false) String keyword,@RequestParam(required=false) BindingStatus status,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(200) int size){return IntegrationBindingPageResponse.from(service.findAll(operationId,providerContractId,keyword,status,page,size));}
@PutMapping("/{id}") public IntegrationBindingResponse update(@PathVariable @Min(1) long id,@Valid @RequestBody UpdateIntegrationBindingRequest r,@RequestHeader("X-Operator") @NotBlank @Size(max=100) String actor){return IntegrationBindingResponse.from(service.update(id,r.bindingName(),r.ownerCode(),r.status(),r.rowVersion(),actor));}}
